// Manual p.91: ten annual payments totaling 150% of principal.
// This reconstruction schedules them on issue-month anniversaries.
export function loanRepaymentSchedule(city,proposedPrincipal=0){if(!Number.isInteger(proposedPrincipal)||proposedPrincipal<0||proposedPrincipal>25000||proposedPrincipal%5000)throw Error('Choose a loan in §5,000 increments up to §25,000.');const dates=new Map(),add=(month,amount,proposed)=>{if(!dates.has(month))dates.set(month,{month,existing:0,proposed:0,loans:0});const row=dates.get(month);row[proposed?'proposed':'existing']+=amount;row.loans++;};for(const loan of city.finance.loans)for(let payment=loan.paymentsMade+1;payment<=10;payment++)add(loan.issuedMonth+payment*12,loan.principal*.15,false);if(proposedPrincipal)for(let payment=1;payment<=10;payment++)add(city.month+payment*12,proposedPrincipal*.15,true);return[...dates.values()].sort((a,b)=>a.month-b.month).map(row=>({...row,total:row.existing+row.proposed,year:city.startYear+Math.floor(row.month/12)}));}
const money=n=>'§'+n.toLocaleString('en-US');
export function loanScheduleReport(city,proposedPrincipal=0){const allowed=city.finance.loans.length<10,principal=allowed?proposedPrincipal:0,rows=loanRepaymentSchedule(city,principal),years=[...new Set(rows.map(row=>row.year))],date=month=>new Date(Date.UTC(city.startYear+Math.floor(month/12),month%12)).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'}),existing=rows.reduce((sum,r)=>sum+r.existing,0),extra=rows.reduce((sum,r)=>sum+r.proposed,0),peak=rows.reduce((best,r)=>!best||r.total>best.total?r:best,null);
 return `<details><summary>Repayment calendar · ${money(existing)} already committed${extra?' · '+money(extra)+' added by the selected loan':''}</summary><p>Existing contracts require ${money(existing)} more in principal and interest.${extra?' The selected '+money(principal)+' loan adds '+money(extra)+' over ten years.':''}${allowed?'':' Ten loans are outstanding; no new loan is included in this preview.'}</p>${peak?`<p>Largest combined payment date: ${date(peak.month)} · ${money(peak.total)}.${peak.month<=city.month?' This date is already due.':''}</p>`:''}${rows.length?years.map(year=>{const group=rows.filter(r=>r.year===year),total=group.reduce((sum,r)=>sum+r.total,0);return `<details><summary>${year} · ${money(total)} due</summary><div class="table-scroll"><table><thead><tr><th>Payment date</th><th>Existing loans</th><th>Selected new loan</th><th>Total</th></tr></thead><tbody>${group.map(r=>`<tr><td>${date(r.month)}${r.month<=city.month?' · due':''}</td><td>${money(r.existing)}</td><td>${money(r.proposed)}</td><td>${money(r.total)}</td></tr>`).join('')}</tbody></table></div></details>`;}).join(''):'<p>No repayments scheduled.</p>'}<p>This is a contractual payment schedule, not a treasury forecast. It excludes future operating revenue, spending, additional borrowing and deals. Changing the principal previews a loan; only Take loan adds it to the city.</p></details>`;
}
